"""Installed-layout Extension compatibility fixture."""

from __future__ import annotations

import os
from pathlib import Path


def record_event(event: str) -> None:
    """Append a lifecycle event when the compatibility probe provides a marker."""
    marker = os.environ.get("PAWNLOGIC_EXTENSION_FIXTURE_MARKER")
    if not marker:
        return
    with Path(marker).open("a", encoding="utf-8") as handle:
        handle.write(f"{event}\n")


record_event("import")
